#pragma once
// Files built into adam.exe (list generated by CMakeLists.txt into the build folder as embedded_files.cpp), so a
// release is just adam.exe + the DLLs: the menus' assets\, the live shell's live\ inputs and SDL's controller database.
// unpack_embedded_files writes the ones the code loads from disk into the data folder at startup.

#include <cstddef>
#include <filesystem>

namespace adam {
    struct EmbeddedFile {
        const char* path;            // relative, with forward slashes ("assets/icons/X.svg")
        const unsigned char* data;
        size_t size;
        bool unpack;                 // false: only used from memory
    };
    extern const EmbeddedFile embedded_files[];
    extern const size_t embedded_file_count;

    const EmbeddedFile* find_embedded_file(const char* path);
    // Writes every unpack file under dir unless an identical copy is already there. False if one couldn't be written.
    bool unpack_embedded_files(const std::filesystem::path& dir);
}
